import sys
import re
plate = sys.stdin.readline().rstrip('\r\n')
def full(pattern):
    return re.fullmatch(pattern, plate) is not None
def mixed(s, letters, digits):
    return (len(s) == letters+digits and
            sum('A' <= c <= 'Z' for c in s) == letters and
            sum('0' <= c <= '9' for c in s) == digits)
def classify():
    if full(r'[0-9]{6}'):
        return 'G6A'
    if full(r'[A-Z]{3}-[A-Z0-9]{3}') and mixed(plate[4:], 1, 2):
        return 'G6B'
    if full(r'[A-Z]{3}-[0-9]{3}'):
        return 'G6C'
    if full(r'[0-9]{3}-[A-Z]{3}'):
        return 'G6D'
    if full(r'[0-9]{7}'):
        return 'G7A'
    if full(r'[A-Z]{3}-[A-Z0-9]{4}') and mixed(plate[4:], 1, 3):
        return 'G7B'
    if full(r'[0-9]{4}[A-Z]{3}'):
        return 'G7C'
    if full(r'[A-Z]{3}[0-9]{4}'):
        return 'G7D'
    if full(r'[A-Z]{2}-[0-9]{5}'):
        return 'G7E'
    if mixed(plate, 3, 4):
        return 'G7F'
    # Vanity must begin with two actual letters, before any optional separator.
    if full(r'[A-Z]{2}[A-Z0-9 -]*'):
        count = sum(c.isalnum() for c in plate)
        if count <= 7 and plate.count('-') + plate.count(' ') <= 1:
            return 'V'
    return 'IV'
print(classify())
